INSERT INTO room_types (slug,name,description,capacity,status,is_demo) VALUES ('chambre-exemple','Chambre — exemple de présentation','Photographie fournie. Nom de catégorie, capacité et équipements à confirmer par l’hôtel.',2,'draft',TRUE) ON CONFLICT (slug) DO NOTHING;
INSERT INTO page_contents (slug,title,body,is_demo) VALUES ('hotel','Le charme de Bassam, la douceur de l’océan','Découvrez le Wharf Hôtel à Grand-Bassam. Les informations détaillées sur l’établissement seront complétées après validation par l’hôtel.',TRUE),('restaurant','Une pause à votre rythme','Présentation du restaurant à confirmer. Contactez l’hôtel pour connaître les menus et les horaires.',TRUE),('piscine-plage','Entre piscine et océan','Les conditions d’accès, les équipements et les horaires seront précisés par l’hôtel.',TRUE),('evenements','Des moments à partager','Mariages, réceptions ou séminaires : présentez votre projet. Les espaces et leurs capacités restent à confirmer.',TRUE),('mentions-legales','Mentions légales','À compléter avant publication : identité et forme juridique de l’exploitant, immatriculation, adresse du siège, directeur de publication et hébergeur.',TRUE),('confidentialite','Politique de confidentialité','Projet à valider avant publication. Les informations de vos formulaires sont destinées au traitement de votre demande par l’hôtel. À compléter : responsable du traitement, base légale, durée de conservation, destinataires, modalités d’exercice des droits et contact.',TRUE) ON CONFLICT (slug) DO NOTHING;
INSERT INTO hotel_settings (setting_key,value) VALUES ('address','Boulevard Treich-Laplène, Quartier France / Plage d’Assoyam'),('phone','+225 27 21 30 15 33'),('email','lewharfhotel@gmail.com'),('facebook','https://www.facebook.com/Wharfhotelbassam/'),('maps','https://www.google.com/maps?q=5.1949396,-3.7355957') ON CONFLICT (setting_key) DO NOTHING;
