INSERT INTO media (url,alt,category,is_demo) SELECT '/photos/15.jpg','Espace extérieur près du bord de mer','Restaurant',TRUE WHERE NOT EXISTS (SELECT 1 FROM media WHERE url='/photos/15.jpg');
